  ('major-00', 'The Fool', 'Kẻ Khờ', 'major', 'major', 'cards/00-TheFool.png', '["khởi đầu", "tự do", "tin tưởng"]'::jsonb, 'Một khởi đầu rộng mở, lời mời bước đi với tâm trí nhẹ nhàng.', 'Sự bốc đồng hoặc nỗi sợ khiến bước chân đầu tiên bị trì hoãn.', 0),
  ('major-01', 'The Magician', 'Nhà Pháp Sư', 'major', 'major', 'cards/01-TheMagician.png', '["ý chí", "khả năng", "hành động"]'::jsonb, 'Bạn đã có những công cụ cần thiết để biến ý định thành hành động.', 'Năng lực đang phân tán hoặc bị dùng thiếu thành thật với chính mình.', 1),
  ('major-02', 'The High Priestess', 'Nữ Tư Tế', 'major', 'major', 'cards/02-TheHighPriestess.png', '["trực giác", "bí ẩn", "tĩnh lặng"]'::jsonb, 'Câu trả lời đến từ quan sát tinh tế và khoảng lặng bên trong.', 'Tiếng ồn bên ngoài đang lấn át trực giác hoặc điều bị che giấu.', 2),
  ('major-03', 'The Empress', 'Hoàng Hậu', 'major', 'major', 'cards/03-TheEmpress.png', '["nuôi dưỡng", "sáng tạo", "sung túc"]'::jsonb, 'Điều được chăm sóc đúng cách đang có cơ hội nảy nở tự nhiên.', 'Bạn có thể đang cho đi quá nhiều mà quên nuôi dưỡng chính mình.', 3),
  ('major-04', 'The Emperor', 'Hoàng Đế', 'major', 'major', 'cards/04-TheEmperor.png', '["cấu trúc", "trách nhiệm", "ranh giới"]'::jsonb, 'Kỷ luật và ranh giới rõ ràng sẽ tạo nền móng vững chắc.', 'Sự kiểm soát cứng nhắc hoặc thiếu cấu trúc đang làm tình thế nặng nề.', 4),
  ('major-05', 'The Hierophant', 'Giáo Hoàng', 'major', 'major', 'cards/05-TheHierophant.png', '["truyền thống", "học hỏi", "niềm tin"]'::jsonb, 'Một hệ giá trị, người thầy hoặc truyền thống có thể chỉ đường.', 'Đã đến lúc tự hỏi quy tắc cũ còn thật sự phù hợp hay không.', 5),
  ('major-06', 'The Lovers', 'Tình Nhân', 'major', 'major', 'cards/06-TheLovers.png', '["lựa chọn", "hòa hợp", "giá trị"]'::jsonb, 'Sự kết nối bền vững bắt đầu từ lựa chọn phù hợp với giá trị sâu nhất.', 'Mâu thuẫn giá trị hoặc thiếu giao tiếp đang tạo khoảng cách.', 6),
  ('major-07', 'The Chariot', 'Cỗ Xe', 'major', 'major', 'cards/07-TheChariot.png', '["tiến bước", "quyết tâm", "định hướng"]'::jsonb, 'Giữ vững hướng đi và điều phối những lực kéo đối nghịch.', 'Vội vàng hoặc mất phương hướng khiến năng lượng bị tiêu hao.', 7),
  ('major-08', 'Strength', 'Sức Mạnh', 'major', 'major', 'cards/08-Strength.png', '["can đảm", "dịu dàng", "nội lực"]'::jsonb, 'Sức mạnh thực sự nằm ở sự kiên nhẫn và cách bạn làm dịu nỗi sợ.', 'Tự nghi ngờ đang che khuất nội lực vốn có của bạn.', 8),
  ('major-09', 'The Hermit', 'Ẩn Sĩ', 'major', 'major', 'cards/09-TheHermit.png', '["chiêm nghiệm", "tìm kiếm", "độc lập"]'::jsonb, 'Lùi lại một nhịp sẽ giúp bạn nhận ra ánh sáng dẫn đường riêng.', 'Sự cô lập kéo dài có thể biến khoảng lặng thành bức tường.', 9),
