  ('major-13', 'Death', 'Chuyển Hóa', 'major', 'major', 'cards/13-Death.png', '["kết thúc", "chuyển hóa", "tái sinh"]'::jsonb, 'Một giai đoạn cần khép lại để chỗ trống cho điều mới hình thành.', 'Bám giữ điều đã hết vòng đời làm quá trình chuyển hóa khó khăn hơn.', 13),
  ('major-14', 'Temperance', 'Tiết Chế', 'major', 'major', 'cards/14-Temperance.png', '["điều hòa", "kiên nhẫn", "hài hòa"]'::jsonb, 'Tiến chậm, pha trộn vừa đủ và tìm nhịp cân bằng bền vững.', 'Cực đoan hoặc thiếu kiên nhẫn đang phá vỡ nhịp điệu tự nhiên.', 14),
  ('major-15', 'The Devil', 'Xiềng Xích', 'major', 'major', 'cards/15-TheDevil.png', '["ràng buộc", "ham muốn", "nhận thức"]'::jsonb, 'Nhìn thẳng vào thói quen hoặc nỗi sợ đang khiến bạn tự trói mình.', 'Bạn bắt đầu nhận ra chiếc khóa và khả năng tự giải phóng.', 15),
  ('major-16', 'The Tower', 'Tòa Tháp', 'major', 'major', 'cards/16-TheTower.png', '["đột phá", "sự thật", "tái cấu trúc"]'::jsonb, 'Một nhận thức bất ngờ phá vỡ cấu trúc không còn chân thật.', 'Bạn cảm nhận thay đổi đến gần nhưng vẫn cố giữ nền móng cũ.', 16),
